class ZoneCounter(StatefulProcessor):
    def init(self, handle):
        self._devices = handle.getMapState("devices", KEY_SCHEMA, VAL_SCHEMA)
        self._timer = handle.getValueState("sweepTimer", TIMER_SCHEMA)

    def handleInputRows(self, key, rows, timerValues):
        now = timerValues.getCurrentProcessingTimeInMs()
        for r in rows:
            self._devices.updateValue(Row(deviceId=r.deviceId), Row(last_ms=now))
        active = self._sweep(now)
        self._ensure_timer(now)  # idempotent: only one pending timer
        yield self._count_row(key[0], active)
